text:
Pick a distance and a route type. Everyone who opens this page on the same day, with the same choices, gets the same route of the day; Another route shuffles. Routes stay on park trails as much as possible and use streets only to link trails up.

function rangeSlider({min, max, step, value, label}) {
  const form = html`&lt;form class="range2"&gt;
    &lt;label&gt;${label}&lt;/label&gt;
    &lt;div class="range2-track"&gt;
      &lt;input type="range" name="lo" min=${min} max=${max} step=${step} value=${value[0]} aria-label="Shortest"&gt;
      &lt;input type="range" name="hi" min=${min} max=${max} step=${step} value=${value[1]} aria-label="Longest"&gt;
    &lt;/div&gt;
    &lt;output name="out"&gt;&lt;/output&gt;
  &lt;/form&gt;`;
  const {lo, hi, out} = form.elements;
  const track = form.querySelector(".range2-track");
  const pct = (v) =&gt; `${(100 * (v - min)) / (max - min)}%`;
  const update = () =&gt; {
    form.value = [+lo.value, +hi.value];
    out.value = `${lo.value}–${hi.value} km`;
    track.style.setProperty("--lo", pct(lo.value));
    track.style.setProperty("--hi", pct(hi.value));
  };
  form.addEventListener("input", (event) =&gt; {
    // Thumbs can't pass each other.
    if (+lo.value &gt; +hi.value) {
      if (event.target === lo) lo.value = hi.value;
      else hi.value = lo.value;
    }
    update();
  });
  form.addEventListener("submit", (event) =&gt; event.preventDefault());
  update();
  return form;
}

DEFAULT_TYPES = ["Loop"]
DEFAULT_KM = [7, 10]

viewof types = Inputs.checkbox(["Loop", "Out-and-back"], {
  label: "Route type",
  value: DEFAULT_TYPES
})
viewof km = rangeSlider({min: 4, max: 12, step: 0.5, value: DEFAULT_KM, label: "Distance"})
viewof again = Inputs.button("Another route")












































routes = FileAttachment("routes.geojson").json()

matching = routes.features.filter(
  (f) =&gt;
    types.map((t) =&gt; t.toLowerCase()).includes(f.properties.type) &&
    f.properties.km &gt;= km[0] &&
    f.properties.km &lt;= km[1]
)

// Today in Vancouver, as YYYY-MM-DD: the seed for the route of the day.
today = new Date().toLocaleDateString("en-CA", {timeZone: "America/Vancouver"})

// FNV-1a string hash: turns the date into a number, the same on every phone.
function hash(text) {
  let h = 2166136261;
  for (const c of text) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  return h &gt;&gt;&gt; 0;
}

// mulberry32: random numbers from a seed. Same seed, same sequence, anywhere.
function seeded(seed) {
  return () =&gt; {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed &gt;&gt;&gt; 15), 1 | seed);
    t = (t + Math.imul(t ^ (t &gt;&gt;&gt; 7), 61 | t)) ^ t;
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}

// Today's order for the matching routes: a Fisher-Yates shuffle seeded by the
// date. Everyone gets the same order; "Another route" steps along it, so no
// route repeats until you've seen them all.
order = {
  const random = seeded(hash(today));
  const idx = matching.map((_, i) =&gt; i);
  for (let i = idx.length - 1; i &gt; 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [idx[i], idx[j]] = [idx[j], idx[i]];
  }
  return idx;
}

// A shared link (…/routes.html?route=&lt;key&gt;) shows that route until you
// change a setting or ask for another.
sharedKey = new URLSearchParams(location.search).get("route")
sharedRoute = routes.features.find((f) =&gt; f.properties.key === sharedKey) ?? null
useShared =
  sharedRoute !== null &&
  again === 0 &&
  types.join() === DEFAULT_TYPES.join() &&
  km.join() === DEFAULT_KM.join()

position = matching.length ? again % matching.length : 0

route = useShared
  ? sharedRoute
  : matching.length
    ? matching[order[position]]
    : null















































































route
  ? html`&lt;div class="route-card"&gt;
      &lt;h3&gt;${route.properties.name}&lt;/h3&gt;
      &lt;p class="route-stats"&gt;
        &lt;strong&gt;${route.properties.km.toFixed(1)} km&lt;/strong&gt; ${route.properties.type} ·
        &lt;strong&gt;↑ ${route.properties.gain_m} m ↓ ${route.properties.loss_m} m&lt;/strong&gt; ·
        ${route.properties.trail_pct}% trail · ${route.properties.street_pct}% street
        &lt;span class="route-id"&gt;· route ${route.properties.id} ·
        ${useShared
          ? "shared with you"
          : `${again === 0 ? "route of the day" : "another route"}: ${position + 1} of ${matching.length} matching routes`}&lt;/span&gt;
      &lt;/p&gt;
      ${sharedKey && !sharedRoute
        ? html`&lt;p class="route-note"&gt;The shared route isn't in the current list
            (routes are rebuilt when the trail data changes), so here's today's route.&lt;/p&gt;`
        : ""}
    &lt;/div&gt;`
  : html`&lt;p&gt;&lt;em&gt;No routes match. Widen the distance or tick another route type.&lt;/em&gt;&lt;/p&gt;`







mapDiv = html`&lt;div class="route-map"&gt;&lt;/div&gt;`







maplibregl = require("maplibre-gl@5.24.0/dist/maplibre-gl.js")

START = [-123.22248, 49.25918] // Park Centre
// Named trails and streets (step 05): context lines and labels.
labels = FileAttachment("labels.geojson").json()
EMPTY = ({type: "FeatureCollection", features: []})

map = {
  const m = new maplibregl.Map({
    container: mapDiv,
    style: "https://tiles.openfreemap.org/styles/positron",
    center: START,
    zoom: 13.5,
    attributionControl: {
      customAttribution: "Trails © OpenStreetMap contributors (ODbL)"
    }
  });
  m.addControl(new maplibregl.NavigationControl(), "top-right");
  await new Promise((resolve) =&gt; m.on("load", resolve));
  m.addSource("route", {type: "geojson", data: EMPTY});
  m.addSource("hover", {type: "geojson", data: EMPTY});
  m.addSource("labels", {type: "geojson", data: labels});
  m.addSource("route-names", {type: "geojson", data: EMPTY});
  const round = {"line-join": "round", "line-cap": "round"};
  // Every named trail, faintly, so you can see what the route passes.
  m.addLayer({id: "trails", type: "line", source: "labels",
              filter: ["==", ["get", "kind"], "trail"], layout: round,
              paint: {"line-color": "#6b8f71", "line-opacity": 0.8,
                      "line-width": ["interpolate", ["linear"], ["zoom"], 12, 0.8, 16, 2]}});
  m.addLayer({id: "route-casing", type: "line", source: "route", layout: round,
              paint: {"line-color": "#fcfcfb", "line-width": 8}});
  m.addLayer({id: "route", type: "line", source: "route", layout: round,
              paint: {"line-color": "#2a78d6", "line-width": 4}});
  // Arrows along the line show which way to run.
  m.addLayer({id: "route-arrows", type: "symbol", source: "route",
              layout: {"symbol-placement": "line", "symbol-spacing": 80,
                       "text-field": "›", "text-font": ["Noto Sans Bold"],
                       "text-size": 22, "text-keep-upright": false,
                       "text-allow-overlap": true},
              paint: {"text-color": "#0b0b0b"}});
  // Names along the lines, for everything the route doesn't use; the route's
  // own trails are named on the route itself (next layer, filled in below).
  const along = (size, font) =&gt; ({
    "symbol-placement": "line", "text-field": ["get", "name"], "text-font": [font],
    "text-size": size, "text-max-angle": 45, "symbol-spacing": 250
  });
  const halo = {"text-halo-color": "#fcfcfb", "text-halo-width": 1.5};
  m.addLayer({id: "street-labels", type: "symbol", source: "labels", minzoom: 13,
              filter: ["==", ["get", "kind"], "street"],
              layout: along(10.5, "Noto Sans Regular"),
              paint: {"text-color": "#52514e", ...halo}});
  m.addLayer({id: "trail-labels", type: "symbol", source: "labels", minzoom: 12.5,
              filter: ["==", ["get", "kind"], "trail"],
              layout: along(11, "Noto Sans Italic"),
              paint: {"text-color": "#3d6b47", ...halo}});
  m.addLayer({id: "route-names", type: "symbol", source: "route-names",
              layout: {"text-field": ["get", "name"], "text-font": ["Noto Sans Bold"],
                       "text-size": 12, "text-variable-anchor": ["left", "right", "top", "bottom"],
                       "text-radial-offset": 0.6},
              paint: {"text-color": "#1c5cab", "text-halo-color": "#fcfcfb", "text-halo-width": 2}});
  // Where the pointer is on the elevation profile.
  m.addLayer({id: "hover", type: "circle", source: "hover",
              paint: {"circle-radius": 7, "circle-color": "#eb6834",
                      "circle-stroke-color": "#fcfcfb", "circle-stroke-width": 2}});
  new maplibregl.Marker({color: "#0b0b0b"})
    .setLngLat(START)
    .setPopup(new maplibregl.Popup().setText("Start and finish: Park Centre"))
    .addTo(m);
  invalidation.then(() =&gt; m.remove());
  return m;
}





































// Draw the chosen route and zoom to it.
{
  map.getSource("route").setData(route ?? EMPTY);
  // Name the route's stretches on the route: a bold label halfway along each
  // named stretch of 300 m or more, from the cue sheet.
  const cues = route ? route.properties.cues : [];
  const profile = route ? route.properties.profile : []; // [km, m, lon, lat] every 50 m
  const nearest = (km) =&gt; profile.reduce((a, b) =&gt; (Math.abs(b[0] - km) &lt; Math.abs(a[0] - km) ? b : a));
  const unnamed = new Set(["unnamed trail", "crossing", "path", "sidewalk", "street"]);
  const named = cues.filter(
    ([label, , km]) =&gt; km &gt;= 0.3 && !unnamed.has(label) && !label.startsWith("Cross ")
  );
  map.getSource("route-names").setData({
    type: "FeatureCollection",
    features: named
      .map(([label, at, km]) =&gt; {
        const [, , lon, lat] = nearest(at + km / 2);
        return {type: "Feature", properties: {name: label},
                geometry: {type: "Point", coordinates: [lon, lat]}};
      })
  });
  // Trails named on the route drop their faint label; everything else keeps it
  // (either spelling: "Salish Trail" = "Salish").
  const keys = [...new Set(named.map(([label]) =&gt; label.replace(/ Trail$/, "")))];
  const onRoute = ["in", ["get", "key"], ["literal", keys]];
  map.setFilter("trail-labels", ["all", ["==", ["get", "kind"], "trail"], ["!", onRoute]]);
  map.setFilter("street-labels", ["all", ["==", ["get", "kind"], "street"], ["!", onRoute]]);
  if (route) {
    const bounds = new maplibregl.LngLatBounds();
    route.geometry.coordinates.forEach((c) =&gt; bounds.extend(c));
    map.fitBounds(bounds, {padding: 40, duration: 500});
  }
}







profile = route
  ? route.properties.profile.map(([km, m, lon, lat]) =&gt; ({km, m, lon, lat}))
  : []

viewof here = {
  if (!route) return html``;
  const low = Math.floor((route.properties.low_m - 5) / 10) * 10;
  return Plot.plot({
    width, // the page column, same as the map
    height: 170,
    marginLeft: 44,
    style: {fontSize: "12px"},
    x: {label: "km →", domain: [0, route.properties.km]},
    y: {label: "↑ elevation (m)", domain: [low, route.properties.high_m + 5], grid: true},
    marks: [
      Plot.areaY(profile, {x: "km", y1: low, y2: "m", fill: "#2a78d6", fillOpacity: 0.12}),
      Plot.lineY(profile, {x: "km", y: "m", stroke: "#2a78d6", strokeWidth: 2}),
      Plot.ruleX(profile, Plot.pointerX({x: "km", stroke: "#52514e"})),
      Plot.dot(profile, Plot.pointerX({x: "km", y: "m", fill: "#eb6834", r: 4})),
      Plot.tip(profile, Plot.pointerX({
        x: "km", y: "m",
        title: (d) =&gt; `${d.km.toFixed(1)} km · ${Math.round(d.m)} m`
      }))
    ]
  });
}
















// Mirror the profile's pointer on the map.
map.getSource("hover").setData(
  here?.lon
    ? {type: "Feature", geometry: {type: "Point", coordinates: [here.lon, here.lat]}}
    : EMPTY
)







function gpx(f) {
  const points = f.geometry.coordinates
    .map(([lon, lat]) =&gt; `&lt;trkpt lat="${lat}" lon="${lon}"&gt;&lt;/trkpt&gt;`)
    .join("\n      ");
  return `&lt;?xml version="1.0" encoding="UTF-8"?&gt;
&lt;gpx version="1.1" creator="psp-trails" xmlns="http://www.topografix.com/GPX/1/1"&gt;
  &lt;trk&gt;
    &lt;name&gt;PSP ${f.properties.id}: ${f.properties.name} (${f.properties.km} km)&lt;/name&gt;
    &lt;trkseg&gt;
      ${points}
    &lt;/trkseg&gt;
  &lt;/trk&gt;
&lt;/gpx&gt;`;
}

// Share: the phone's share sheet (messages, WhatsApp, email, Strava, ...).
// The text has a link that opens this exact route; the GPX goes along where
// the phone allows files. With no share sheet, the text goes to the clipboard.
function shareRoute(f) {
  const p = f.properties;
  const link = `${location.origin}${location.pathname}?route=${p.key}`;
  const text = [
    `${p.name}: ${p.km.toFixed(1)} km ${p.type}, ↑${p.gain_m} m ↓${p.loss_m} m,`,
    "from the Park Centre (Cleveland Trail & W 16th Ave)",
    link,
    "",
    ...p.directions.map(([at, full]) =&gt; `${at.toFixed(1)} km  ${full}`)
  ].join("\n");
  const title = `Pacific Spirit run: ${p.name}`;
  const file = new File([gpx(f)], `psp-${p.id}.gpx`, {type: "application/gpx+xml"});
  const quietly = (e) =&gt; { if (e.name !== "AbortError") throw e; }; // user cancelled
  if (navigator.canShare?.({files: [file]})) {
    return navigator.share({title, text, files: [file]}).catch(quietly);
  }
  if (navigator.share) return navigator.share({title, text}).catch(quietly);
  return navigator.clipboard.writeText(text).then(() =&gt; "copied");
}

function shareButton(f) {
  const button = html`&lt;button class="btn btn-quarto" type="button"&gt;Share&lt;/button&gt;`;
  button.onclick = async () =&gt; {
    if ((await shareRoute(f)) === "copied") {
      button.textContent = "Copied ✓";
      setTimeout(() =&gt; (button.textContent = "Share"), 2000);
    }
  };
  return button;
}

route
  ? html`&lt;div class="route-actions"&gt;
      ${DOM.download(
        () =&gt; new Blob([gpx(route)], {type: "application/gpx+xml"}),
        `psp-${route.properties.id}.gpx`,
        "Download GPX"
      )}
      ${shareButton(route)}
    &lt;/div&gt;`
  : html``






























Printable card
For runners who’d rather leave the phone at home: the route’s outline and every turn with the km it comes at. Pick a card size, print, and cut along the dashed lines. The preview is the real printed size; the text shrinks until the whole route fits.

LAYOUTS = [
  {n: 2, cols: 1, rows: 2, font: 13, size: "7.9 × 5.2 in"},
  {n: 4, cols: 2, rows: 2, font: 10, size: "3.9 × 5.2 in"},
  {n: 8, cols: 2, rows: 4, font: 8, size: "3.9 × 2.6 in, palm size"},
  {n: 10, cols: 2, rows: 5, font: 8, size: "3.9 × 2.1 in, business card"},
  {n: 12, cols: 3, rows: 4, font: 8, size: "2.6 × 2.6 in, sticky note"}
].map((l) =&gt; ({...l, w: 7.9 / l.cols, h: 10.4 / l.rows, compact: l.n &gt;= 8}))

// Buttons, not a dropdown: always visible, and no oversized native menu.
viewof layout = Inputs.radio(LAYOUTS, {
  label: "Cards per page",
  format: (l) =&gt; String(l.n),
  value: LAYOUTS[2]
})

html`&lt;p class="layout-size"&gt;Each card ${layout.size}&lt;/p&gt;`





















route
  ? html`&lt;div class="route-actions"&gt;
      ${Inputs.button("Print cards", {reduce: () =&gt; printCards(route, layout)})}
    &lt;/div&gt;`
  : html``









function esc(text) {
  return String(text).replace(/[&&lt;&gt;"]/g, (c) =&gt; ({"&": "&amp;", "&lt;": "&lt;", "&gt;": "&gt;", '"': "&quot;"})[c]);
}

function outline(f, size) {
  // Route shape, north up, scaled to fit a square.
  const pts = f.geometry.coordinates;
  const k = Math.cos((pts[0][1] * Math.PI) / 180);
  const xs = pts.map(([lon]) =&gt; lon * k), ys = pts.map(([, lat]) =&gt; lat);
  const [x0, x1, y0, y1] = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  const scale = (size - 12) / Math.max(x1 - x0, y1 - y0);
  const dx = (size - (x1 - x0) * scale) / 2, dy = (size - (y1 - y0) * scale) / 2;
  const P = pts.map((_, i) =&gt; [dx + (xs[i] - x0) * scale, size - dy - (ys[i] - y0) * scale]);
  const line = P.map(([x, y]) =&gt; `${x.toFixed(1)},${y.toFixed(1)}`).join(" ");
  const i = Math.floor(P.length * 0.08); // an arrow early on shows the direction
  const [ax, ay] = P[i], [bx, by] = P[Math.min(i + 3, P.length - 1)];
  const angle = (Math.atan2(by - ay, bx - ax) * 180) / Math.PI;
  return `&lt;svg class="pc-outline" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}"&gt;
    &lt;polyline points="${line}" fill="none" stroke="#0b0b0b" stroke-width="2" stroke-linejoin="round"/&gt;
    &lt;path d="M -5 -4 L 4 0 L -5 4 z" fill="#0b0b0b" transform="translate(${bx.toFixed(1)} ${by.toFixed(1)}) rotate(${angle.toFixed(0)})"/&gt;
    &lt;circle cx="${P[0][0].toFixed(1)}" cy="${P[0][1].toFixed(1)}" r="4" fill="#fff" stroke="#0b0b0b" stroke-width="2"/&gt;
    &lt;text x="${size - 2}" y="10" text-anchor="end" font-size="9" font-weight="700"&gt;N↑&lt;/text&gt;
  &lt;/svg&gt;`;
}

function cardHtml(f, layout) {
  const p = f.properties;
  const steps = p.directions
    .map(([at, , short]) =&gt; `&lt;li&gt;&lt;b&gt;${at.toFixed(1)}&lt;/b&gt; ${esc(short)}&lt;/li&gt;`)
    .join("");
  const stats = `${p.km.toFixed(1)} km ${esc(p.type)} · ↑${p.gain_m} ↓${p.loss_m} m`;
  if (layout.compact) {
    // Directions get the full height; outline, start and legend sit at the side.
    const columns = layout.n === 10 ? 3 : 2; // short, wide cards: three columns
    return `&lt;div class="pc pc-compact"&gt;
      &lt;div class="pc-head"&gt;&lt;span class="pc-name"&gt;${esc(p.name)}&lt;/span&gt;&lt;span class="pc-stats"&gt;${stats}&lt;/span&gt;&lt;/div&gt;
      &lt;ol class="pc-steps" style="columns: ${columns}"&gt;${steps}&lt;/ol&gt;
      &lt;div class="pc-side"&gt;${outline(f, 58)}
        &lt;div&gt;○ Park Centre&lt;/div&gt;
        &lt;div class="pc-legend"&gt;←→ turn&lt;br&gt;↖↗ slight&lt;br&gt;T T-junction&lt;br&gt;Y fork&lt;br&gt;↑ straight&lt;br&gt;WC toilets&lt;/div&gt;
        &lt;div&gt;${esc(p.id)}&lt;/div&gt;
      &lt;/div&gt;
    &lt;/div&gt;`;
  }
  return `&lt;div class="pc"&gt;
    &lt;div class="pc-head"&gt;
      &lt;div class="pc-name"&gt;${esc(p.name)}&lt;/div&gt;
      &lt;div class="pc-stats"&gt;${stats} · ${p.trail_pct}% trail&lt;/div&gt;
    &lt;/div&gt;
    &lt;div class="pc-body"&gt;
      &lt;div class="pc-side"&gt;${outline(f, 110)}&lt;div class="pc-start"&gt;○ Park Centre&lt;br&gt;Cleveland &amp; W 16th&lt;/div&gt;&lt;/div&gt;
      &lt;ol class="pc-steps"&gt;${steps}&lt;/ol&gt;
    &lt;/div&gt;
    &lt;div class="pc-foot"&gt;
      &lt;span&gt;← → turn · ↖↗ slight · ↙↘ sharp · T T-junction · Y fork · ↑ straight · WC toilets&lt;/span&gt;
      &lt;span&gt;${esc(p.id)} · pstrunners.github.io&lt;/span&gt;
    &lt;/div&gt;
  &lt;/div&gt;`;
}

CARD_CSS = `
