// Shrink the text until the directions fit on the card (no hidden overflow).
function fitCards(root, start) {
  const cards = [...root.querySelectorAll(".pc")];
  const card = cards[0], steps = card.querySelector(".pc-steps");
  const over = () =&gt;
    card.scrollHeight &gt; card.clientHeight + 1 ||
    steps.scrollHeight &gt; steps.clientHeight + 1 ||
    steps.scrollWidth &gt; steps.clientWidth + 1;
  let size = start;
  const apply = () =&gt; cards.forEach((c) =&gt; (c.style.fontSize = `${size}pt`));
  apply();
  while (over() && size &gt; 5) {
    size -= 0.25;
    apply();
  }
  return size;
}

function printCards(f, layout) {
  const page = `&lt;!doctype html&gt;&lt;html&gt;&lt;head&gt;&lt;meta charset="utf-8"&gt;
    &lt;title&gt;PSP ${esc(f.properties.id)} cards&lt;/title&gt;
    &lt;style&gt;${CARD_CSS}
      @page { size: letter; margin: 0.3in; }
      body { margin: 0; }
      .sheet { display: grid; width: 7.9in;
               grid-template-columns: repeat(${layout.cols}, ${layout.w}in);
               grid-template-rows: repeat(${layout.rows}, ${layout.h}in); }
    &lt;/style&gt;&lt;/head&gt;
    &lt;body&gt;&lt;div class="sheet"&gt;${cardHtml(f, layout).repeat(layout.n)}&lt;/div&gt;
    &lt;script&gt;${fitCards.toString()}
      window.onload = () =&gt; { fitCards(document, ${layout.font}); window.print(); };
    &lt;\/script&gt;&lt;/body&gt;&lt;/html&gt;`;
  const w = window.open("", "_blank");
  w.document.write(page);
  w.document.close();
}

cardPreview = {
  if (!route) return html``;
  const box = html`&lt;div class="card-preview"&gt;&lt;style&gt;${CARD_CSS}&lt;/style&gt;&lt;/div&gt;`;
  box.insertAdjacentHTML("beforeend", cardHtml(route, layout));
  const card = box.querySelector(".pc");
  card.style.width = `${layout.w}in`;
  card.style.height = `${layout.h}in`;
  yield box; // on the page, so the browser can measure it
  fitCards(box, layout.font);
}




















































